module teleportation (\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] N,\n    input [7:0] str0_char0,\n    input [7:0] str0_char1,\n    input [7:0] str0_char2,\n    input [7:0] str0_char3,\n    input [1:0] len0,\n    input [7:0] str1_char0,\n    input [7:0] str1_char1,\n    input [7:0] str1_char2,\n    input [7:0] str1_char3,\n    input [1:0] len1,\n    input [7:0] str2_char0,\n    input [7:0] str2_char1,\n    input [7:0] str2_char2,\n    input [7:0] str2_char3,\n    input [1:0] len2,\n    input [7:0] str3_char0,\n    input [7:0] str3_char1,\n    input [7:0] str3_char2,\n    input [7:0] str3_char3,\n    input [1:0] len3,\n    output [2:0] result,\n    output done\n);\n\n    // Internal registers\n    reg [7:0] str_reg [0:3][0:3];\n    reg [1:0] len_reg [0:3];\n    reg [1:0] N_reg;\n    reg [2:0] dp [0:3];\n    reg [2:0] result_reg;\n    reg done_reg;\n    reg [2:0] state;\n    reg [1:0] i_reg, j_reg;\n    reg [2:0] dp_temp;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    // State definitions\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] LOAD          = 3'd1;\n    localparam [2:0] COMPUTE_START = 3'd2;\n    localparam [2:0] COMPUTE_OUTER = 3'd3;\n    localparam [2:0] COMPUTE_INNER = 3'd4;\n    localparam [2:0] UPDATE_DP     = 3'd5;\n    localparam [2:0] FIND_MAX      = 3'd6;\n    localparam [2:0] DONE_STATE    = 3'd7;\n\n    // Valid pair signals\n    wire [0:0] valid_pair [0:3][0:3];\n\n    // Generate valid pair logic\n    genvar gj, gi, k;\n    generate\n        for (gj = 0; gj < 4; gj = gj + 1) begin: gen_j\n            for (gi = 0; gi < 4; gi = gi + 1) begin: gen_i\n                wire len_ok = (len_reg[gj] <= len_reg[gi]);\n                wire [3:0] prefix_match;\n                wire [3:0] suffix_match;\n                for (k = 0; k < 4; k = k + 1) begin: loop_k\n                    assign prefix_match[k] = (k < len_reg[gj]) ? (str_reg[gj][k] == str_reg[gi][k]) : 1'b1;\n                    assign suffix_match[k] = (k < len_reg[gj]) ? (str_reg[gj][k] == str_reg[gi][len_reg[gi]-len_reg[gj]+k]) : 1'b1;\n                end\n                wire all_prefix_ok = &prefix_match;\n                wire all_suffix_ok = &suffix_match;\n                assign valid_pair[gj][gi] = len_ok && all_prefix_ok && all_suffix_ok;\n            end\n        end\n    endgenerate\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done_reg <= 1'b0;\n            result_reg <= 3'd0;\n            N_reg <= 2'd0;\n            for (integer i = 0; i < 4; i = i + 1) begin\n                len_reg[i] <= 2'd0;\n                dp[i] <= 3'd1;\n                for (integer j = 0; j < 4; j = j + 1) begin\n                    str_reg[i][j] <= 8'd0;\n                end\n            end\n            i_reg <= 2'd0;\n            j_reg <= 2'd0;\n            dp_temp <= 3'd1;\n            cycle_count <= 8'd0;\n        end else begin\n            cycle_count <= (state == IDLE) ? 8'd0 : (cycle_count + 8'd1);\n            case (state)\n                IDLE: begin\n                    done_reg <= 1'b0;\n                    if (start) begin\n                        state <= LOAD;\n                    end\n                end\n                LOAD: begin\n                    N_reg <= N;\n                    str_reg[0][0] <= str0_char0;\n                    str_reg[0][1] <= str0_char1;\n                    str_reg[0][2] <= str0_char2;\n                    str_reg[0][3] <= str0_char3;\n                    len_reg[0] <= len0;\n                    str_reg[1][0] <= str1_char0;\n                    str_reg[1][1] <= str1_char1;\n                    str_reg[1][2] <= str1_char2;\n                    str_reg[1][3] <= str1_char3;\n                    len_reg[1] <= len1;\n                    str_reg[2][0] <= str2_char0;\n                    str_reg[2][1] <= str2_char1;\n                    str_reg[2][2] <= str2_char2;\n                    str_reg[2][3] <= str2_char3;\n                    len_reg[2] <= len2;\n                    str_reg[3][0] <= str3_char0;\n                    str_reg[3][1] <= str3_char1;\n                    str_reg[3][2] <= str3_char2;\n                    str_reg[3][3] <= str3_char3;\n                    len_reg[3] <= len3;\n                    state <= COMPUTE_START;\n                end\n                COMPUTE_START: begin\n                    i_reg <= 2'd0;\n                    dp[0] <= 3'd1;\n                    dp[1] <= 3'd1;\n                    dp[2] <= 3'd1;\n                    dp[3] <= 3'd1;\n                    state <= COMPUTE_OUTER;\n                end\n                COMPUTE_OUTER: begin\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= DONE_STATE;\n                    end else if (i_reg >= N_reg) begin\n                        state <= FIND_MAX;\n                    end else begin\n                        j_reg <= 2'd0;\n                        dp_temp <= 3'd1;\n                        state <= COMPUTE_INNER;\n                    end\n                end\n                COMPUTE_INNER: begin\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= DONE_STATE;\n                    end else if (j_reg < i_reg) begin\n                        if (valid_pair[j_reg][i_reg] && (dp[j_reg] + 3'd1 > dp_temp)) begin\n                            dp_temp <= dp[j_reg] + 3'd1;\n                        end\n                        j_reg <= j_reg + 2'd1;\n                    end else begin\n                        state <= UPDATE_DP;\n                    end\n                end\n                UPDATE_DP: begin\n                    dp[i_reg] <= dp_temp;\n                    i_reg <= i_reg + 2'd1;\n                    state <= COMPUTE_OUTER;\n                end\n                FIND_MAX: begin\n                    result_reg <= 3'd1;\n                    if (N_reg >= 2'd1 && dp[0] > result_reg) result_reg <= dp[0];\n                    if (N_reg >= 2'd2 && dp[1] > result_reg) result_reg <= dp[1];\n                    if (N_reg >= 2'd3 && dp[2] > result_reg) result_reg <= dp[2];\n                    if (N_reg == 2'd3 && dp[3] > result_reg) result_reg <= dp[3];\n                    state <= DONE_STATE;\n                end\n                DONE_STATE: begin\n                    done_reg <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\n    assign result = result_reg;\n    assign done = done_reg;\n\nendmodule